      (function () {
        const slides = Array.from(document.querySelectorAll('.slide'));
        const total = slides.length;
        let current = slides.findIndex(s => s.classList.contains('active'));
        if (current < 0) {
          current = 0;
          slides[0].classList.add('active');
        }

        function go(n) {
          n = Math.max(0, Math.min(total - 1, n));
          if (n === current) return;
          slides[current].classList.remove('active');
          slides[n].classList.add('active');
          current = n;
          // Reset scroll in case anything inside the slide was scrolled.
          window.scrollTo(0, 0);
        }

        document.addEventListener('keydown', e => {
          if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
          if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ' || e.key === 'PageDown') {
            e.preventDefault();
            go(current + 1);
          } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp' || e.key === 'PageUp') {
            e.preventDefault();
            go(current - 1);
          } else if (e.key === 'Home') {
            e.preventDefault();
            go(0);
          } else if (e.key === 'End') {
            e.preventDefault();
            go(total - 1);
          }
        });

        // Touch swipe (mobile / trackpad)
        let touchStartX = 0;
        let touchStartY = 0;
        document.addEventListener('touchstart', e => {
          touchStartX = e.changedTouches[0].clientX;
          touchStartY = e.changedTouches[0].clientY;
        }, { passive: true });
        document.addEventListener('touchend', e => {
          const dx = e.changedTouches[0].clientX - touchStartX;
          const dy = e.changedTouches[0].clientY - touchStartY;
          if (Math.abs(dx) < 50 && Math.abs(dy) < 50) return;
          if (Math.abs(dx) > Math.abs(dy)) {
            go(current + (dx < 0 ? 1 : -1));
          } else {
            go(current + (dy < 0 ? 1 : -1));
          }
        }, { passive: true });

        // Mouse wheel — locked for 700ms to prevent multi-skip on trackpads
        let wheelLocked = false;
        document.addEventListener('wheel', e => {
          if (wheelLocked) return;
          const primary = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
          if (Math.abs(primary) < 5) return;
          go(current + (primary > 0 ? 1 : -1));
          wheelLocked = true;
          setTimeout(() => { wheelLocked = false; }, 700);
        }, { passive: true });
      })();
